insert into public.piezas (codigo_marcado, ref_code, herramienta, metros_perforados, metro_garantizado, estado, fecha_inicio, precio_usd)
select c.codigo, nullif(c.ref, '~'), r.herramienta, 0, r.garantizado, 'RESERVA', c.entrega::date, r.precio
from codigos c join refs r on r.ref = c.ref
on conflict (codigo_marcado) do nothing;

-- Verificación: debe devolver 411 (o más, si ya habías registrado alguno en bodega)
select count(*) as en_bodega from public.piezas where estado = 'RESERVA';
